            !useEmberlensPipeline &&
            !anchorForcesAlloyium &&
            (anchorForcesNvidium ||
             (effectivePrefs.AllowSinytra &&
              portStrategy != "native-forge" &&
              effectivePrefs.Gpu == "nvidia" &&
              !effectivePrefs.UseShaders &&
              !isPotato));

