            ? issue.BetweenIds.Select(id => new ConflictChoiceOption(
                id,
                $"Оставить {(ModDatabase.ModById.TryGetValue(id, out var m) ? m.Name : id)}",
                id == issue.KeepPreferredId)).ToList()
            : [];
